#' Map spatial predictions
#'
#' Draws maps of predicted biomass and/or richness from an `sf` object of
#' prediction locations (grid cells or points), for one or several years, with
#' optional visualisation of posterior uncertainty, a boundary layer and a
#' chosen display CRS. The result is an ordinary `ggplot2` object that can be
#' customised with `+`.
#'
#' @section Prediction and mapping are separate:
#' Predictions are generated by [predict.bm_fit()] and can be expensive for a
#' fine grid. Compute them once, for example
#' `pred <- predict(model, grid, random = c(locality = "marginal"), n_draws = 300)`,
#' and pass `pred` as `prediction_data`; drawing or redrawing maps then does not
#' call the model. If `prediction_data` has no prediction columns (`response`,
#' `median`, `mean`, `sd`, `lower`, `upper`) predictions are computed here with
#' `predict_args` (default: expected response, locality and replication effects
#' marginalised, 500 draws) and a message says so.
#'
#' @section What is mapped:
#' By default the posterior `statistic` of the **expected response** (see
#' [predict.bm_fit()]). With `uncertainty = "width"` (or `TRUE`) the map shows the
#' credible-interval width (`upper - lower`), with `"sd"` the posterior standard
#' deviation, and with `"alpha"` the statistic is drawn with transparency that
#' increases with the interval width. The uncertainty of a map of expected
#' responses reflects parameter (and simulated random-effect) uncertainty, not
#' observation noise; use `type = "predictive"` predictions for prediction
#' intervals.
#'
#' @section Several responses and years:
#' Years are facets (columns by default). Biomass and richness are on different
#' scales: with `scale = "shared"` all panels share one colour scale (sensible
#' for one response, or years); `scale = "relative"` rescales each response to
#' 0-1 within itself so responses can be shown side by side. It is usually
#' clearer to map responses separately.
#'
#' @param model A `bm_fit` object (used for column names, CRS and, if needed,
#'   predictions).
#' @param prediction_data An `sf` object (points, or polygons whose geometry is
#'   mapped), or a data frame with the model's coordinate columns. Either the
#'   result of `predict(model, ...)` or locations (plus covariates, year, season)
#'   for which predictions are to be computed.
#' @param response One or more fitted responses.
#' @param year `NULL` (all years in the data) or the years to show; needs the
#'   year column of the model.
#' @param statistic `"median"` (default), `"mean"`, `"sd"`, `"lower"` or `"upper"`.
#' @param uncertainty `FALSE`, `TRUE`/`"width"`, `"sd"` or `"alpha"`; see above.
#' @param boundary An `sf` layer (for example country or region borders) drawn on
#'   top; transformed to the CRS of the predictions.
#' @param facet_by `"year"` (years as columns) or `"response"` (responses as
#'   columns).
#' @param scale `"shared"` or `"relative"`; see above.
#' @param crs Display CRS (anything `sf::st_crs()` accepts); default the CRS of
#'   the predictions.
#' @param predict_args List of arguments overriding the defaults used when
#'   predictions have to be computed here.
#' @param point_size Size of the squares used for point predictions.
#' @return A `ggplot2` object.
#' @export
#' @examples
#' \donttest{
#' sim <- simulate_bm_data(n_year = 4, n_locality = 20, n_rep = 3, seed = 3,
#'                         spatial = "coordinates")
#' fit <- fit_model(sim, responses = "biomass", spatial_effect = "coordinates",
#'                  random_effects = "year", n_chains = 2, n_iter = 2000,
#'                  n_burnin = 1000, n_thin = 2, seed = 1, parallel = FALSE)
#' grid <- sf::st_make_grid(sf::st_as_sfc(sf::st_bbox(c(xmin = 5, xmax = 15, ymin = 58,
#'                          ymax = 68), crs = 4326)), n = c(12, 12))
#' grid <- sf::st_sf(year = 2021, geometry = grid)
#' pred <- predict(fit, grid, random = c(year = "zero"), n_draws = 200)  # expensive step
#' plot_spatial_predictions(fit, pred, "biomass", uncertainty = FALSE)
#' plot_spatial_predictions(fit, pred, "biomass", uncertainty = "width")
#' }
#' @md
plot_spatial_predictions <- function(model, prediction_data, response = "biomass",
                                     year = NULL,
                                     statistic = c("median", "mean", "sd", "lower", "upper"),
                                     uncertainty = FALSE, boundary = NULL,
                                     facet_by = c("year", "response"),
                                     scale = c("shared", "relative"), crs = NULL,
                                     predict_args = list(), point_size = 1.5) {
  statistic <- match.arg(statistic)
  facet_by <- match.arg(facet_by)
  scale <- match.arg(scale)
  response <- bm_check_responses(model, response)
  unc <- if (isFALSE(uncertainty)) "none" else if (isTRUE(uncertainty)) "width" else uncertainty
  if (!is.character(unc) || length(unc) != 1L || !unc %in% c("none", "width", "sd", "alpha")) {
    stop("`uncertainty` must be FALSE, TRUE, 'width', 'sd' or 'alpha'.", call. = FALSE)
  }
  if (!is.numeric(point_size) || length(point_size) != 1L || point_size <= 0) {
    stop("`point_size` must be a positive number.", call. = FALSE)
  }
  if (!is.data.frame(prediction_data)) {
    stop("`prediction_data` must be an sf object or a data frame.", call. = FALSE)
  }
  cols <- model$spec$columns
  model_crs <- if (!is.null(model$prep$spatial)) model$prep$spatial$options$crs else 4326
  pred_cols <- c("response", "median", "mean", "sd", "lower", "upper")

  pd <- prediction_data
  if (!all(pred_cols %in% names(pd))) {
    defaults <- list(type = "expected", n_draws = 500, level = 0.95,
                     random = bm_default_map_random(model))
    args <- utils::modifyList(defaults, predict_args)
    message("Computing predictions for the map; to avoid repeating this, compute ",
            "predict() once and pass the result as `prediction_data`.")
    pd <- do.call(stats::predict, c(list(model, pd, responses = response), args))
  }
  if (!inherits(pd, "sf")) {
    xy <- c(cols$longitude, cols$latitude)
    if (is.null(xy) || !all(xy %in% names(pd))) {
      stop("`prediction_data` needs an sf geometry or the coordinate columns '",
           paste(xy, collapse = "', '"), "'.", call. = FALSE)
    }
    pd <- sf::st_as_sf(pd, coords = xy, crs = model_crs, remove = FALSE)
  }
  if (is.na(sf::st_crs(pd))) sf::st_crs(pd) <- sf::st_crs(model_crs)
  if (!all(pred_cols %in% names(pd))) {
    stop("`prediction_data` lacks prediction columns: ",
         paste(setdiff(pred_cols, names(pd)), collapse = ", "), ".", call. = FALSE)
  }

  pd <- pd[pd$response %in% response, ]
  if (!nrow(pd)) stop("`prediction_data` has no rows for the requested response(s).", call. = FALSE)
  ycol <- cols$year
  if (!is.null(ycol) && ycol %in% names(pd)) {
    if (!is.null(year)) {
      pd <- pd[pd[[ycol]] %in% year, ]
      if (!nrow(pd)) stop("No prediction rows for year(s): ", paste(year, collapse = ", "), ".", call. = FALSE)
    }
    pd$.year <- factor(pd[[ycol]])
  } else {
    if (!is.null(year)) stop("`prediction_data` has no year column ('", ycol, "').", call. = FALSE)
    pd$.year <- factor("all")
  }

  pd$.width <- pd$upper - pd$lower
  pd$.value <- switch(unc, none = pd[[statistic]], width = pd$.width, sd = pd$sd,
                      alpha = pd[[statistic]])
  if (scale == "relative") {
    pd$.value <- stats::ave(pd$.value, pd$response, FUN = function(v) {
      r <- range(v, na.rm = TRUE)
      if (diff(r) == 0) rep(0.5, length(v)) else (v - r[1]) / diff(r)
    })
  }
  stat_lab <- c(median = "Posterior median", mean = "Posterior mean", sd = "Posterior sd",
                lower = "Lower bound", upper = "Upper bound")[[statistic]]
  fill_lab <- if (scale == "relative") {
    "Relative value\n(0-1 per response)"
  } else switch(unc, none = stat_lab, width = "Credible\ninterval width",
                sd = "Posterior sd", alpha = stat_lab)

  pts <- all(as.character(sf::st_geometry_type(pd)) %in% c("POINT", "MULTIPOINT"))
  p <- ggplot2::ggplot(pd)
  alpha_aes <- unc == "alpha"
  if (pts) {
    p <- p + if (alpha_aes) {
      ggplot2::geom_sf(ggplot2::aes(colour = .data$.value, alpha = .data$.width),
                       shape = 15, size = point_size)
    } else {
      ggplot2::geom_sf(ggplot2::aes(colour = .data$.value), shape = 15, size = point_size)
    }
    p <- p + ggplot2::scale_colour_viridis_c(name = fill_lab, na.value = "grey85")
  } else {
    p <- p + if (alpha_aes) {
      ggplot2::geom_sf(ggplot2::aes(fill = .data$.value, alpha = .data$.width), colour = NA)
    } else {
      ggplot2::geom_sf(ggplot2::aes(fill = .data$.value), colour = NA)
    }
    p <- p + ggplot2::scale_fill_viridis_c(name = fill_lab, na.value = "grey85")
  }
  if (alpha_aes) {
    p <- p + ggplot2::scale_alpha_continuous(name = "Credible\ninterval width",
                                             range = c(1, 0.2))
  }
  if (!is.null(boundary)) {
    if (!inherits(boundary, c("sf", "sfc"))) stop("`boundary` must be an sf or sfc object.", call. = FALSE)
    if (is.na(sf::st_crs(boundary))) sf::st_crs(boundary) <- sf::st_crs(pd)
    boundary <- sf::st_transform(boundary, sf::st_crs(pd))
    p <- p + ggplot2::geom_sf(data = boundary, inherit.aes = FALSE, fill = NA,
                              colour = "grey20", linewidth = 0.3)
  }
  if (!is.null(crs)) p <- p + ggplot2::coord_sf(crs = sf::st_crs(crs))

  n_y <- nlevels(pd$.year)
  n_r <- length(unique(pd$response))
  p <- p + if (facet_by == "year") {
    if (n_y > 1L && n_r > 1L) ggplot2::facet_grid(response ~ .year)
    else if (n_y > 1L) ggplot2::facet_wrap(~ .year)
    else if (n_r > 1L) ggplot2::facet_wrap(~ response)
    else NULL
  } else {
    if (n_y > 1L && n_r > 1L) ggplot2::facet_grid(.year ~ response)
    else if (n_r > 1L) ggplot2::facet_wrap(~ response)
    else if (n_y > 1L) ggplot2::facet_wrap(~ .year)
    else NULL
  }
  if (n_y > 1L || n_r > 1L) p <- p + ggplot2::scale_x_continuous(n.breaks = 3)
  p + ggplot2::theme_minimal()
}

# For maps of unsampled locations: integrate over the site and replicate level
# effects, keep the year effects
bm_default_map_random <- function(model) {
  eff <- model$spec$random_effects
  if (!length(eff)) return("conditional")
  modes <- stats::setNames(rep("conditional", length(eff)), eff)
  modes[names(modes) %in% c("locality", "replication")] <- "marginal"
  modes
}
